// 3.2-second trimmed/resampled piano, retaining its pitched body and decay.
// Attribution and source: audio/piano/CREDITS.txt.
const SAMPLE_RATE=22050;
const PIANO_PCM="";
export function createInlinePiano(context){
 const bytes=atob(PIANO_PCM),buffer=context.createBuffer(1,bytes.length/2,SAMPLE_RATE),data=buffer.getChannelData(0);let peak=0;
 for(let i=0;i<data.length;i++){const word=bytes.charCodeAt(i*2)|(bytes.charCodeAt(i*2+1)<<8);data[i]=(word>32767?word-65536:word)/32768;peak=Math.max(peak,Math.abs(data[i]));}
 return {buffer,offset:0,normalization:peak>.001?.68/peak:1};
}
